"""Local data, diagnostics, and repository challenge preparation."""
import datetime
import gzip
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import sqlite3
import subprocess
import sys
import uuid


def state_dir():
    home = os.environ.get('HOME')
    if home is None:
        import pwd
        home = pwd.getpwuid(os.getuid()).pw_dir
    return Path(home) / '.gittype'


def timestamp():
    return datetime.datetime.now().strftime('%Y%m%d_%H%M%S')


class Diagnostics:
    def __init__(self):
        self.root = state_dir()
        self.started = timestamp()
        self.log = self.root/'logs'/('gittype_'+self.started+'.log')
        try:
            self.log.parent.mkdir(parents=True, exist_ok=True)
            self.write('INFO','gittype::infrastructure::logging',f'GitType logging initialized, logs saved to: {self.log.parent}')
        except OSError:
            pass

    def write(self, level, target, text):
        try:
            with self.log.open('a') as f:
                date=datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                f.write(f'{date} [{level}] {target} - {text}\n')
        except OSError:
            pass

    def error(self, message):
        now=datetime.datetime.now(datetime.timezone.utc)
        details = (f'ERROR OCCURRED AT: {now.strftime("%Y-%m-%d %H:%M:%S UTC")}\n'
                   'ERROR TYPE: "gittype::domain::error::GitTypeError"\n'
                   f'ERROR MESSAGE: {message}\n'
                   f'EXECUTABLE: {json.dumps(os.path.abspath(sys.argv[0]),ensure_ascii=False)}\n'
                   f'WORKING_DIR: {json.dumps(os.getcwd(),ensure_ascii=False)}\n'
                   f'COMMAND_ARGS: {json.dumps(sys.argv,ensure_ascii=False)}\n'
                   f'RUST_LOG: {os.environ.get("RUST_LOG", "not set")}\n'
                   'OS: linux\nARCH: x86_64\n')
        self.write('ERROR','gittype::infrastructure::logging','APPLICATION ERROR:\n'+details)
        filename='gittype_error_'+timestamp()+'.log'
        try:
            with open(filename,'a') as f:
                f.write(details+'\n')
            sys.stderr.write('💾 Error details written to: '+filename+'\n')
        except OSError:
            pass
        sys.stderr.write('Error: '+message+'\n')
        return 1


def cache_dir():
    dest=state_dir()/'cache'
    try:
        dest.mkdir(parents=True,exist_ok=True)
    except OSError:
        return Path('.')
    return dest


def human_size(size):
    if size<1024:
        return f'{size} bytes'
    if size<1024**2:
        return f'{size/1024:.1f} KB'
    if size<1024**3:
        return f'{size/(1024**2):.1f} MB'
    return f'{size/(1024**3):.1f} GB'


def cache_command(command,diagnostics):
    path=cache_dir()
    try:
        files=[p for p in path.iterdir() if p.is_file()]
        if command=='stats':
            size=sum(p.stat().st_size for p in files)
            print(f'Challenge Cache Statistics:\n  Cached repositories: {len(files)}\n  Total size: {human_size(size)}')
        elif command=='clear':
            for p in files:
                p.unlink()
            print('Challenge cache cleared successfully.')
        else:
            keys=sorted(p.stem for p in files if p.suffix=='.bin')
            if not keys:
                print('No cached challenges found.')
            else:
                print('Cached repositories:')
                for key in keys:
                    print('  '+key)
        return 0
    except OSError as e:
        return diagnostics.error(f'I/O error: {e.strerror} (os error {e.errno})')


def cached_repos():
    root=state_dir()/'repos'
    if not root.is_dir():
        return []
    repos=[]
    for owner in root.iterdir():
        if owner.is_dir():
            for repo in owner.iterdir():
                if repo.is_dir() and not repo.name.startswith('.'):
                    repos.append((owner.name+'/'+repo.name,repo))
    return sorted(repos)


def clear_repos(force,diagnostics):
    root=state_dir()/'repos'
    if not root.exists():
        print('No cached repositories directory found.')
        return 0
    repos=cached_repos()
    if not repos:
        print('No cached repositories found.')
        return 0
    if not force:
        print(f'Found {len(repos)} cached repositories.')
        print('Are you sure you want to clear all cached repositories? (y/N): ',end='',flush=True)
        answer=sys.stdin.readline().strip().lower()
        if answer not in ('y','yes'):
            print('Operation cancelled.')
            return 0
    try:
        shutil.rmtree(root)
        print(f'Successfully cleared {len(repos)} cached repositories.')
        return 0
    except OSError as e:
        return diagnostics.error(f'I/O error: {e.strerror} (os error {e.errno})')


TABLES = {
'repositories': '''id INTEGER PRIMARY KEY, user_name TEXT NOT NULL, repository_name TEXT NOT NULL,
 remote_url TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_name,repository_name)''',
'sessions': '''id INTEGER PRIMARY KEY, repository_id INTEGER, started_at DATETIME NOT NULL,
 completed_at DATETIME, branch TEXT, commit_hash TEXT, is_dirty BOOLEAN DEFAULT FALSE,
 game_mode TEXT NOT NULL, difficulty_level TEXT, max_stages INTEGER, time_limit_seconds INTEGER,
 FOREIGN KEY(repository_id) REFERENCES repositories(id)''',
'challenges': '''id TEXT PRIMARY KEY, file_path TEXT, start_line INTEGER, end_line INTEGER,
 language TEXT, code_content TEXT NOT NULL, comment_ranges TEXT, difficulty_level TEXT,
 created_at DATETIME DEFAULT CURRENT_TIMESTAMP''',
'stages': '''id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL, challenge_id TEXT NOT NULL,
 stage_number INTEGER NOT NULL, started_at DATETIME, completed_at DATETIME,
 FOREIGN KEY(session_id) REFERENCES sessions(id), FOREIGN KEY(challenge_id) REFERENCES challenges(id)''',
'session_results': '''id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL, repository_id INTEGER NOT NULL,
 keystrokes INTEGER NOT NULL, mistakes INTEGER NOT NULL, duration_ms INTEGER NOT NULL, wpm REAL, cpm REAL,
 accuracy REAL, stages_completed INTEGER NOT NULL, stages_attempted INTEGER NOT NULL,
 stages_skipped INTEGER NOT NULL, partial_effort_keystrokes INTEGER DEFAULT 0,
 partial_effort_mistakes INTEGER DEFAULT 0, best_stage_wpm REAL, worst_stage_wpm REAL,
 best_stage_accuracy REAL, worst_stage_accuracy REAL, score REAL, rank_name TEXT, tier_name TEXT,
 rank_position INTEGER, rank_total INTEGER, position INTEGER, total INTEGER, game_mode TEXT,
 difficulty_level TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(session_id) REFERENCES sessions(id), FOREIGN KEY(repository_id) REFERENCES repositories(id)''',
'stage_results': '''id INTEGER PRIMARY KEY, stage_id INTEGER NOT NULL, session_id INTEGER NOT NULL,
 repository_id INTEGER NOT NULL, keystrokes INTEGER NOT NULL, mistakes INTEGER NOT NULL,
 duration_ms INTEGER NOT NULL, wpm REAL, cpm REAL, accuracy REAL, consistency_streaks TEXT,
 score REAL, rank_name TEXT, tier_name TEXT, rank_position INTEGER, rank_total INTEGER,
 position INTEGER, total INTEGER, was_skipped BOOLEAN DEFAULT FALSE, was_failed BOOLEAN DEFAULT FALSE,
 completed_at DATETIME NOT NULL, language TEXT, difficulty_level TEXT,
 FOREIGN KEY(stage_id) REFERENCES stages(id), FOREIGN KEY(session_id) REFERENCES sessions(id),
 FOREIGN KEY(repository_id) REFERENCES repositories(id)'''
}


def initialize_database():
    dest=state_dir()/'gittype.db'
    try:
        dest.parent.mkdir(parents=True,exist_ok=True)
        db=sqlite3.connect(dest)
        for table,columns in TABLES.items():
            db.execute(f'CREATE TABLE IF NOT EXISTS {table} ({columns})')
        for table,cols,idx in [('stage_results','repository_id, completed_at','repo_date'),('stage_results','language','language'),('stage_results','session_id','session'),('session_results','repository_id, created_at','repo_date'),('sessions','repository_id, started_at','repo_date')]:
            db.execute(f'CREATE INDEX IF NOT EXISTS idx_{table}_{idx} ON {table} ({cols})')
        db.commit()
        db.close()
    except (OSError,sqlite3.Error):
        pass


def run_git(path,*args):
    try:
        return subprocess.check_output(['git','-C',str(path),*args],stderr=subprocess.DEVNULL,timeout=3).decode().strip()
    except (subprocess.SubprocessError,OSError,UnicodeError):
        return ''


EXTENSIONS = {'.rs':'rust','.py':'python','.pyi':'python','.ts':'typescript','.tsx':'typescript','.js':'javascript','.jsx':'javascript','.mjs':'javascript','.cjs':'javascript','.rb':'ruby','.go':'go','.swift':'swift','.kt':'kotlin','.kts':'kotlin','.java':'java','.php':'php','.cs':'csharp','.c':'c','.h':'c','.cpp':'cpp','.cc':'cpp','.cxx':'cpp','.hpp':'cpp','.hs':'haskell','.dart':'dart','.scala':'scala','.sc':'scala','.zig':'zig','.clj':'clojure','.cljs':'clojure','.cljc':'clojure'}
DISPLAY_LANGUAGES = {'c':'C','cpp':'C++','csharp':'C#','javascript':'JavaScript','typescript':'TypeScript','php':'PHP'}


def display_language(language):
    return DISPLAY_LANGUAGES.get(language,language.capitalize())


class Repository:
    def __init__(self,options):
        self.challenges=[]
        self.name=''
        self.branch=''
        self.commit=''
        self.dirty=False
        self.url=''
        self.error=''
        self.root=Path.cwd()
        self.options=options

    def load(self):
        if self.options.repo:
            spec=self.options.repo
            match=re.match(r'^(?:https?://github.com/|git@github.com:)?([^/\s]+)/([^/\s]+?)(?:\.git)?/?$',spec)
            if match:
                self.name=match[1]+'/'+match[2]
                cached=state_dir()/'repos'/match[1]/match[2]
                if cached.is_dir():
                    self.root=cached
                else:
                    self.name=''
                    self.error='Failed to clone repository'
                    return
            else:
                self.error='Invalid repository format'
                return
        top=run_git(self.root,'rev-parse','--show-toplevel')
        url=run_git(self.root,'remote','get-url','origin')
        commit=run_git(self.root,'rev-parse','HEAD')
        if not top or not url or not re.fullmatch('[a-fA-F0-9]{40}',commit):
            self.error='Git repository not found'
            return
        self.root=Path(top)
        self.url=url
        clean=re.sub(r'\.git$','',url.rstrip('/'))
        clean=clean.replace('git@github.com:','https://github.com/')
        parts=clean.split('/')
        self.name='/'.join(parts[-2:])
        self.branch=run_git(self.root,'rev-parse','--abbrev-ref','HEAD')
        self.commit=commit
        self.dirty=bool(run_git(self.root,'status','--porcelain'))
        scan=self.root
        if self.options.repo_path and not self.options.repo:
            scan=Path(self.options.repo_path)
            if not scan.exists():
                self.error='Path does not exist: '+str(scan)
                return
        for folder,dirs,files in os.walk(scan):
            dirs[:]=sorted(d for d in dirs if not d.startswith('.') and d not in ('node_modules','target','vendor','build','dist','__pycache__'))
            for file in sorted(files):
                path=Path(folder)/file
                language=EXTENSIONS.get(path.suffix.lower())
                if not language:
                    continue
                try:
                    code=path.read_text()
                    if len(code)>500000 or not code.strip():
                        continue
                    label=str(path.relative_to(scan))
                    self.extract(label,language,code)
                except (OSError,UnicodeError,ValueError):
                    pass
        if len(self.challenges)<10000:
            self.save_cache()

    def extract(self,path,lang,code):
        lines=code.rstrip('\n').splitlines()
        if not lines:
            return
        chunks=[(1,len(lines))]
        if lang=='python':
            import ast
            try:
                tree=ast.parse(code)
                for node in ast.walk(tree):
                    if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):
                        chunks.append((node.lineno,node.end_lineno))
            except (SyntaxError,ValueError):
                pass
        else:
            starts=[]
            for n,line in enumerate(lines):
                if '{' in line and re.search(r'\b(fn|func|function|class|struct|enum|interface|trait|impl)\b|\)\s*(?:->.*?)?\s*\{',line):
                    level=0
                    for last in range(n,len(lines)):
                        level+=lines[last].count('{')-lines[last].count('}')
                        if level<=0:
                            if last>=n:
                                starts.append((n+1,last+1))
                            break
            chunks+=starts
        for start,end in chunks:
            text='\n'.join(lines[start-1:end])+'\n'
            if len(text.strip())<10:
                continue
            for diff,target,minsize in [('Easy',100,0),('Normal',200,100),('Hard',500,300),('Wild',None,0)]:
                if len(text)<minsize:
                    continue
                last=end
                value=text
                if target and len(text)>target:
                    chosen=[];length=0
                    for line in lines[start-1:end]:
                        if chosen and length+len(line)+1>target:
                            break
                        chosen.append(line);length+=len(line)+1
                    last=start+len(chosen)-1
                    value='\n'.join(chosen)+'\n'
                self.challenges.append(dict(id=str(uuid.uuid4()),path=path,start=start,end=last,language=lang,difficulty=diff,code=value))
        self.challenges.append(dict(id=str(uuid.uuid4()),path=path,start=1,end=len(lines),language=lang,difficulty='Zen',code='\n'.join(lines)+'\n'))

    def available(self,difficulty,languages):
        return [c for c in self.challenges if c['difficulty']==difficulty and (not languages or c['language'] in languages)]

    def save_cache(self):
        # The compact cache contains locations, rather than a copy of source files.
        def number(v):
            out=bytearray()
            while v>127:
                out.append((v&127)|128);v>>=7
            out.append(v)
            return bytes(out)
        def string(s):
            d=s.encode();return number(len(d))+d
        try:
            key=re.sub('[^a-zA-Z0-9]','_',re.sub(r'^https?://|^git@','',self.url.removesuffix('.git'))).strip('_')
            content=string(key)+string(self.commit)+number(len(self.challenges))
            for c in self.challenges:
                content+=string(c['id'])+b'\1'+string(c['path'])+b'\1'+number(c['start'])+b'\1'+number(c['end'])+b'\1'+string(c['language'])+b'\0\1'+number(['Easy','Normal','Hard','Wild','Zen'].index(c['difficulty']))
            digest=hashlib.sha256((key+'_'+self.commit).encode()).hexdigest()
            path=cache_dir()/(digest+'.bin')
            if not path.exists():
                path.write_bytes(gzip.compress(content,mtime=0))
        except OSError:
            pass
PY"}

