    try:
        dest.mkdir(parents=True,exist_ok=True)
    except OSError:
        return Path('.')
    return dest


def human_size(size):
    if size<1024:
        return f'{size} bytes'
    if size<1024**2:
        return f'{size/1024:.1f} KB'
    if size<1024**3:
        return f'{size/(1024**2):.1f} MB'
    return f'{size/(1024**3):.1f} GB'


def cache_command(command,diagnostics):
    path=cache_dir()
    try:
        files=[p for p in path.iterdir() if p.is_file()]
        if command=='stats':
            size=sum(p.stat().st_size for p in files)
            print(f'Challenge Cache Statistics:\n  Cached repositories: {len(files)}\n  Total size: {human_size(size)}')
        elif command=='clear':
            for p in files:
                p.unlink()
            print('Challenge cache cleared successfully.')
        else:
            keys=sorted(p.stem for p in files if p.suffix=='.bin')
            if not keys:
                print('No cached challenges found.')
            else:
                print('Cached repositories:')
                for key in keys:
                    print('  '+key)
        return 0
    except OSError as e:
        return diagnostics.error(f'I/O error: {e.strerror} (os error {e.errno})')


def cached_repos():
    root=state_dir()/'repos'
    if not root.is_dir():
        return []
    repos=[]
    for owner in root.iterdir():
        if owner.is_dir():
            for repo in owner.iterdir():
                if repo.is_dir() and not repo.name.startswith('.'):
                    repos.append((owner.name+'/'+repo.name,repo))
    return sorted(repos)


def clear_repos(force,diagnostics):
    root=state_dir()/'repos'
    if not root.exists():
        print('No cached repositories directory found.')
        return 0
    repos=cached_repos()
    if not repos:
        print('No cached repositories found.')
        return 0
    if not force:
        print(f'Found {len(repos)} cached repositories.')
        print('Are you sure you want to clear all cached repositories? (y/N): ',end='',flush=True)
        answer=sys.stdin.readline().strip().lower()
        if answer not in ('y','yes'):
            print('Operation cancelled.')
            return 0
    try:
        shutil.rmtree(root)
        print(f'Successfully cleared {len(repos)} cached repositories.')
        return 0
    except OSError as e:
        return diagnostics.error(f'I/O error: {e.strerror} (os error {e.errno})')


