            return logs.error('Validation error: Unsupported language: '+options.language)
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        return logs.error('Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)')
    from ui import Application
    try:
        return Application(options,logs).run()
    except KeyboardInterrupt:
        return 0
    except OSError as error:
        return logs.error(f'Terminal error: {error.strerror} (os error {error.errno})')


if __name__=='__main__':
