        return 1
    if options.command.startswith('cache '):
        return cache_command(options.command[6:],logs)
    if options.command=='repo clear':
        return clear_repos(options.force,logs)
    if not options.command:
        logs.write('INFO','gittype::presentation::cli::commands::game','Starting GitType game session')
        logs.write('WARN','gittype::domain::repositories::version_repository','Failed to fetch latest version from API: Failed to extract code chunks: Failed to fetch release: error sending request for url (https://api.github.com/repos/unhappychoice/gittype/releases/latest)')
        invalid=[s for s in options.langs if s.lower() not in LANGUAGES]
        if invalid:
